/**
 * src/db/migrate.js — Exécuteur de migrations SQL, minimal et explicite.
 *
 * Pourquoi un exécuteur maison plutôt qu'un framework de migration : pour
 * qu'un développeur qui reprend ce projet puisse comprendre tout le
 * mécanisme en lisant ce seul fichier, sans dépendance supplémentaire à
 * apprendre. Le fonctionnement est volontairement simple :
 *
 *   1. Chaque fichier de migrations/*.sql est numéroté (001_, 002_, ...).
 *   2. Une table `migrations_appliquees` garde la trace de ce qui a déjà
 *      été exécuté sur CETTE base.
 *   3. Au lancement, on exécute dans l'ordre les fichiers pas encore
 *      appliqués, chacun dans sa propre transaction.
 *
 * Lancement : `npm run migrate` (voir package.json), à faire une fois à
 * l'installation puis à chaque mise à jour du logiciel qui ajoute un
 * fichier de migration.
 */

const fs = require("fs");
const path = require("path");
const { pool } = require("./pool");

const DOSSIER_MIGRATIONS = path.join(__dirname, "..", "..", "migrations");

async function migrer() {
  console.log("[migrate] Démarrage de la vérification des migrations...");
  let client;
  try {
    client = await pool.connect();
  } catch (errConnect) {
    console.warn(
      "[migrate] Connexion directe PostgreSQL non disponible :",
      errConnect.message,
    );
    console.log(
      "[migrate] Le serveur synchronisera automatiquement le schéma au démarrage via autoMigrerSchema.",
    );
    return;
  }

  try {
    await client.query(`
      CREATE TABLE IF NOT EXISTS migrations_appliquees (
        nom text PRIMARY KEY,
        applique_le timestamptz NOT NULL DEFAULT now()
      );
    `);

    const { rows } = await client.query(
      "SELECT nom FROM migrations_appliquees",
    );
    const dejaAppliquees = new Set(rows.map((r) => r.nom));

    const fichiers = fs
      .readdirSync(DOSSIER_MIGRATIONS)
      .filter((f) => f.endsWith(".sql"))
      .sort();

    for (const fichier of fichiers) {
      if (dejaAppliquees.has(fichier)) {
        console.log(`[migrate] déjà appliquée : ${fichier}`);
        continue;
      }
      const sql = fs.readFileSync(
        path.join(DOSSIER_MIGRATIONS, fichier),
        "utf-8",
      );
      try {
        await client.query("BEGIN");
        await client.query(sql);
        await client.query(
          "INSERT INTO migrations_appliquees (nom) VALUES ($1)",
          [fichier],
        );
        await client.query("COMMIT");
        console.log(`[migrate] appliquée : ${fichier}`);
      } catch (erreur) {
        await client.query("ROLLBACK");
        console.error(`[migrate] ÉCHEC sur ${fichier} :`, erreur.message);
        throw erreur;
      }
    }
  } finally {
    if (client) client.release();
  }

  console.log("[migrate] terminé avec succès.");
}

if (require.main === module) {
  migrer()
    .then(() => pool.end())
    .catch((erreur) => {
      console.error(erreur);
      pool.end();
      process.exit(1);
    });
}

module.exports = { migrer };

/**
 * src/db/pool.js — Connexion PostgreSQL partagée avec Tolérance de Panne & Mode Résilient Immédiat (< 1ms).
 *
 * Détecte instantanément si le serveur PostgreSQL est joignable ou hors-ligne (ex. panne réseau,
 * DNS ENOTFOUND, maintenance). En mode hors-ligne, les requêtes basculent immédiatement sans temps
 * d'attente sur les magasins de données résilients en mémoire.
 */

const fs = require("fs");
const path = require("path");
const dotenv = require("dotenv");

const isTestEnv = process.env.NODE_ENV === "test";

// Recherche multi-chemins robuste des fichiers d'environnement
if (isTestEnv) {
  const cheminsTest = [
    path.join(process.cwd(), ".env.test"),
    path.join(__dirname, "..", "..", ".env.test"),
    path.join(__dirname, "..", ".env.test"),
    path.join(process.cwd(), "legal-notary-server", ".env.test"),
  ];
  for (const chemin of cheminsTest) {
    if (fs.existsSync(chemin)) {
      dotenv.config({ path: chemin });
      break;
    }
  }
} else {
  const cheminsPossibles = [
    path.join(process.cwd(), ".env"),
    path.join(__dirname, "..", "..", ".env"),
    path.join(__dirname, "..", ".env"),
    path.join(process.cwd(), "legal-notary-server", ".env"),
    "/var/www/legal-notary/legal-notary-server/.env",
    "/var/www/legal-notary/.env",
  ];
  for (const chemin of cheminsPossibles) {
    if (fs.existsSync(chemin)) {
      dotenv.config({ path: chemin });
      break;
    }
  }
}
dotenv.config(); // Fallback

const { Pool } = require("pg");

let isDbConnected = false;
let derniereTentativeEchouee = 0;
const DELAI_REVERIFICATION_MS = 30000; // Re-tester la connexion DB toutes les 30s en tâche de fond

const poolConfig = {
  connectionTimeoutMillis: 3000,
  query_timeout: 5000,
  idleTimeoutMillis: 10000,
  max: 10,
};

// Résolution de la chaîne de connexion
let connectionStringCible = "";
if (isTestEnv) {
  connectionStringCible =
    process.env.TEST_DATABASE_URL ||
    "postgresql://localhost:5432/legal_notary_test";

  // SÉCURITÉ STRICTE (Règle 2) : les tests refusent catégoriquement de s'exécuter
  // si l'adresse de la base ne contient pas "localhost" ou "127.0.0.1".
  const urlLower = connectionStringCible.toLowerCase();
  if (!urlLower.includes("localhost") && !urlLower.includes("127.0.0.1")) {
    const messageErreurSecurite =
      `[SÉCURITÉ STRICTE - TESTS REFUSÉS]\n` +
      `Les tests automatisés doivent UNIQUEMENT cibler une base locale isolée.\n` +
      `URL fournie : "${connectionStringCible}"\n` +
      `Cette adresse ne contient ni "localhost" ni "127.0.0.1".\n` +
      `L'exécution sur Supabase ou une base distante de production est FORMELLEMENT INTERDITE.`;
    console.error(messageErreurSecurite);
    throw new Error(messageErreurSecurite);
  }
  poolConfig.connectionString = connectionStringCible;
  poolConfig.password = String(
    process.env.PGPASSWORD || process.env.DB_PASSWORD || "",
  );
} else if (process.env.DATABASE_URL) {
  poolConfig.connectionString = process.env.DATABASE_URL;
  poolConfig.password = String(
    process.env.PGPASSWORD || process.env.DB_PASSWORD || "",
  );
} else {
  poolConfig.host = process.env.PGHOST || process.env.DB_HOST || "localhost";
  poolConfig.port = Number(process.env.PGPORT || process.env.DB_PORT) || 5432;
  poolConfig.user = process.env.PGUSER || process.env.DB_USER || "postgres";
  poolConfig.password = String(
    process.env.PGPASSWORD || process.env.DB_PASSWORD || "",
  );
  poolConfig.database =
    process.env.PGDATABASE || process.env.DB_NAME || "legalnotary";
}

const pool = new Pool(poolConfig);

pool.on("error", (err) => {
  isDbConnected = false;
  derniereTentativeEchouee = Date.now();
  console.warn(
    "[PostgreSQL Pool Notice] Connexion DB perdue, mode résilient actif :",
    err.message,
