        utilisateur.id,
        `Relance interne envoyée à ${nomClerc || "clerc assigné"}`,
      );
      return true;
    });
  } catch (_) {}

  await ajouterMouvement(
    null,
    dossierId,
    utilisateur ? utilisateur.id : "user",
    `Relance interne envoyée à ${nomClerc || "clerc assigné"}`,
  );
