/**
 * Génère ou récupère un token d'accès public sécurisé pour le remplissage KYC du dossier.
 */
async function genererOuRecupererTokenKyc(dossierId, utilisateurId) {
  try {
    const dossierRes = await pool.query(
      `SELECT d.id, d.numero_dossier, d.montant_assiette, ta.libelle AS type_acte_libelle,
              COALESCE((SELECT string_agg(c.nom, ', ') FROM dossier_comparants c WHERE c.dossier_id = d.id), '') AS comparants_noms
       FROM dossiers d
       JOIN types_actes ta ON ta.id = d.type_acte_id
       WHERE d.id = $1`,
      [dossierId],
    );

    if (dossierRes.rows && dossierRes.rows.length) {
      const dossier = dossierRes.rows[0];
      const kycRes = await pool.query(
        "SELECT id, token_acces, statut, type_personne, donnees_kyc, signature_client, signe_le, signe_a FROM dossier_kyc WHERE dossier_id = $1",
        [dossierId],
      );

      let kycRow;
      if (kycRes.rows && kycRes.rows.length) {
        kycRow = kycRes.rows[0];
      } else {
        const token = crypto.randomBytes(24).toString("hex");
        const insertRes = await pool.query(
          `INSERT INTO dossier_kyc (dossier_id, token_acces, statut, type_personne, cree_par)
           VALUES ($1, $2, 'en_attente', 'physique', $3)
           RETURNING id, token_acces, statut, type_personne, donnees_kyc, signature_client, signe_le, signe_a`,
          [dossierId, token, utilisateurId || null],
        );
        kycRow = insertRes.rows[0];
      }

      return {
        dossierId: dossier.id,
        numeroDossier: dossier.numero_dossier,
        typeActe: dossier.type_acte_libelle,
        comparantsNoms: dossier.comparants_noms,
        token: kycRow.token_acces,
        statut: kycRow.statut,
        typePersonne: kycRow.type_personne,
        donnees: kycRow.donnees_kyc || {},
        signature: kycRow.signature_client,
        signeLe: kycRow.signe_le,
        signeA: kycRow.signe_a,
      };
    }
  } catch (errDb) {
    // Repli mémoire
  }

  const dossiersService = require("./dossiers.service");
  const d = (
    await dossiersService.listerDossiersPourUtilisateur({ role: "notaire" })
  ).find((it) => it.id === dossierId) || {
    id: dossierId,
    numeroDossier: "DOS-2026-001",
    typeActeId: "vente_immobiliere",
    comparantsNoms: "Client Comparant",
    montantAssiette: 50000000,
  };

  let memoire = KYC_MEMOIRE.get(dossierId);
  if (!memoire) {
    const token = "kyc-token-" + Date.now();
    memoire = {
      id: "kyc-" + Date.now(),
      dossier_id: dossierId,
      token_acces: token,
      statut: "en_attente",
      type_personne: "physique",
      donnees_kyc: {},
      signature_client: null,
      signe_le: null,
      signe_a: null,
      created_at: new Date().toISOString(),
    };
    KYC_MEMOIRE.set(dossierId, memoire);
  }

  return {
    dossierId: d.id,
    numeroDossier: d.numeroDossier,
    typeActe: d.typeActeId || "Vente Immobilière",
    comparantsNoms: d.comparantsNoms || "Client",
    token: memoire.token_acces,
    statut: memoire.statut,
    typePersonne: memoire.type_personne,
    donnees: memoire.donnees_kyc || {},
    signature: memoire.signature_client,
    signeLe: memoire.signe_le,
    signeA: memoire.signe_a,
  };
}

/**
 * Récupère les données publiques pour afficher le formulaire KYC au client ayant scanné le QR Code.
 */
async function obtenirFormulaireKycPublic(token) {
  if (!token || typeof token !== "string") {
    const err = new Error("Token d'accès invalide");
    err.status = 400;
    throw err;
  }

  const kycRes = await pool.query(
    `SELECT k.id, k.dossier_id, k.token_acces, k.statut, k.type_personne, k.donnees_kyc, k.signature_client, k.signe_le, k.signe_a,
            d.numero_dossier, d.montant_assiette, ta.libelle AS type_acte_libelle,
            COALESCE((SELECT string_agg(c.nom, ', ') FROM dossier_comparants c WHERE c.dossier_id = d.id), '') AS comparants_noms
     FROM dossier_kyc k
     JOIN dossiers d ON d.id = k.dossier_id
     JOIN types_actes ta ON ta.id = d.type_acte_id
     WHERE k.token_acces = $1`,
    [token],
  );

  if (!kycRes.rows.length) {
    const err = new Error("Lien KYC expiré ou introuvable");
    err.status = 404;
    throw err;
  }

  const kyc = kycRes.rows[0];

  // Paramètres de l'étude pour l'en-tête officiel
  const parametresService = require("./parametres.service");
  const params = await parametresService.obtenir();

  return {
    token: kyc.token_acces,
    statut: kyc.statut,
    typePersonne: kyc.type_personne,
    dossier: {
      id: kyc.dossier_id,
      numeroDossier: kyc.numero_dossier,
      typeActe: kyc.type_acte_libelle,
      comparantsNoms: kyc.comparants_noms,
      montantAssiette: Number(kyc.montant_assiette) || 0,
    },
    etude: {
      nomEtude: params.nomEtude || "OFFICE NOTARIAL",
      titreNotaire: params.titreNotaire || "Maître",
      nomNotaire: params.nomNotaire || "",
      numeroOffice: params.numeroOrdre || "Office Notarial",
      adresse: params.adresse || "Abidjan, Côte d'Ivoire",
      boitePostale: params.boitePostale || "",
      telephone:
        params.telephoneFixe ||
        params.telephonePortable ||
        params.telephone ||
        "",
      email: params.email || "",
    },
    donnees: kyc.donnees_kyc || {},
    signature: kyc.signature_client,
    signeLe: kyc.signe_le,
    signeA: kyc.signe_a,
  };
}

/**
 * Enregistre les réponses du client et sa signature tactile.
 */
async function soumettreKycClient(token, payload, ip, userAgent) {
  if (!token) {
    const err = new Error("Token manquant");
    err.status = 400;
    throw err;
  }

  const kycRes = await pool.query(
    "SELECT id, dossier_id, statut FROM dossier_kyc WHERE token_acces = $1",
    [token],
  );

  if (!kycRes.rows.length) {
    const err = new Error("Fiche KYC introuvable");
    err.status = 404;
    throw err;
  }

  const kycId = kycRes.rows[0].id;
  const dossierId = kycRes.rows[0].dossier_id;

  const donneesKyc = payload.donnees || payload;
  const signatureClient = payload.signature || donneesKyc.signature || null;
  const signeA = payload.signeA || donneesKyc.signeA || "Abidjan";
  const typePersonne =
    payload.typePersonne || donneesKyc.typePersonne || "physique";

  const updateRes = await pool.query(
    `UPDATE dossier_kyc
     SET statut = 'renseigne',
         type_personne = $1,
         donnees_kyc = $2,
         signature_client = $3,
         signe_le = NOW(),
         signe_a = $4,
         ip_client = $5,
         user_agent_client = $6,
         updated_at = NOW()
     WHERE id = $7
     RETURNING id, dossier_id, token_acces, statut, type_personne, donnees_kyc, signature_client, signe_le, signe_a`,
    [
      typePersonne,
      JSON.stringify(donneesKyc),
      signatureClient,
      signeA,
      ip || null,
      userAgent || null,
      kycId,
    ],
  );

  // Mettre à jour le nom du comparant dans le dossier s'il a été renseigné
  if (donneesKyc.nomPrenoms && donneesKyc.nomPrenoms.trim()) {
    const nomComplet = donneesKyc.nomPrenoms.trim();
    const compExist = await pool.query(
      "SELECT id FROM dossier_comparants WHERE dossier_id = $1",
      [dossierId],
    );
    if (!compExist.rows.length) {
      await pool.query(
        "INSERT INTO dossier_comparants (dossier_id, nom, qualite) VALUES ($1, $2, 'Client principal')",
        [dossierId, nomComplet],
      );
    }
  }

  return updateRes.rows[0];
}

/**
 * Récupère la fiche KYC pour l'office notarial (vue authentifiée).
 */
async function obtenirKycDossier(dossierId) {
  const kycRes = await pool.query(
    `SELECT k.id, k.dossier_id, k.token_acces, k.statut, k.type_personne, k.donnees_kyc, k.signature_client, k.signe_le, k.signe_a,
            k.created_at, k.updated_at, k.valide_le,
            u.nom_complet AS valide_par_nom
     FROM dossier_kyc k
     LEFT JOIN utilisateurs u ON u.id = k.valide_par
     WHERE k.dossier_id = $1`,
    [dossierId],
  );

  if (!kycRes.rows.length) {
    return null;
  }

  const kyc = kycRes.rows[0];
  return {
    id: kyc.id,
    dossierId: kyc.dossier_id,
    token: kyc.token_acces,
    statut: kyc.statut,
    typePersonne: kyc.type_personne,
    donnees: kyc.donnees_kyc || {},
    signature: kyc.signature_client,
    signeLe: kyc.signe_le,
    signeA: kyc.signe_a,
    valideLe: kyc.valide_le,
    valideParNom: kyc.valide_par_nom,
    createdAt: kyc.created_at,
    updatedAt: kyc.updated_at,
  };
}

/**
 * Valide la fiche KYC par le notaire ou le clerc.
 */
async function validerKycDossier(dossierId, utilisateurId) {
  const res = await pool.query(
    `UPDATE dossier_kyc
     SET statut = 'valide',
         valide_par = $1,
         valide_le = NOW(),
         updated_at = NOW()
     WHERE dossier_id = $2
     RETURNING id, statut, valide_le`,
    [utilisateurId, dossierId],
  );

  if (!res.rows.length) {
    const err = new Error("Aucune fiche KYC à valider pour ce dossier");
    err.status = 404;
    throw err;
  }

  return res.rows[0];
}

module.exports = {
  genererOuRecupererTokenKyc,
  obtenirFormulaireKycPublic,
  soumettreKycClient,
  obtenirKycDossier,
  validerKycDossier,
};

/**
 * src/services/manuel-procedure.service.js — Manuel de procédure du pipeline.
 *
 * Demande explicite du 2026-08-25 : « un paramètre sur le manuel de
 * procédure... qui fait quoi, les différentes étapes et niveaux d'alerte ».
 * Les 6 étapes du pipeline (voir migration 002, table `etapes_pipeline`)
 * étaient jusque-là une liste fixe dans le code — elles vivent maintenant
 * en base : le cabinet peut décrire/corriger qui est responsable de
 * chaque étape et son niveau d'alerte sans reprise de développement.
 *
 * Ce qui reste structurel (non éditable, car c'est la mécanique même du
 * pipeline) : le nombre d'étapes (toujours 6), leur ordre (id 1 à 6), et
 * leur `code` (utilisé ailleurs dans le code, ex. alertes.service.js).
 * Ce qui est éditable : `description`, `role_responsable`,
 * `niveau_alerte_par_defaut`.
 */

const { pool } = require("../db/pool");
const fs = require("fs");
const path = require("path");

function versCamel(l) {
  return {
    id: Number(l.id),
    code: l.code,
    libelle: l.libelle,
    description: l.description || "",
    roleResponsable:
      l.role_responsable || l.roleResponsable || "clerc_redacteur",
    niveauAlerteParDefaut:
      l.niveau_alerte_par_defaut || l.niveauAlerteParDefaut || "normal",
  };
}

const ETAPES_INITIALES = [
  {
    id: 1,
    code: "COLLECTE_KYC",
    libelle: "Collecte & KYC",
    description:
      "Vérification CNI/passeport, extrait < 3 mois, livret de famille / KYC personne morale.",
    roleResponsable: "assistante",
    niveauAlerteParDefaut: "normal",
  },
  {
    id: 2,
    code: "REQUISITIONS",
    libelle: "Réquisitions & états préalables",
    description: "Conservation Foncière, TCA, certificat d'urbanisme, RCCM.",
    roleResponsable: "clerc_redacteur",
    niveauAlerteParDefaut: "normal",
  },
  {
    id: 3,
    code: "REDACTION",
    libelle: "Rédaction du projet d'acte",
    description:
      "Rédaction de la minute, insertion des clauses, contrôle notarial de légalité.",
    roleResponsable: "clerc_redacteur",
    niveauAlerteParDefaut: "eleve",
  },
  {
    id: 4,
    code: "SIGNATURE",
    libelle: "Rendez-vous de signature",
    description:
      "Lecture de l'acte, recueil des signatures des comparants et du Notaire Titulaire.",
    roleResponsable: "notaire",
    niveauAlerteParDefaut: "eleve",
  },
  {
    id: 5,
    code: "FORMALITES",
    libelle: "Formalités DGI & Conservation Foncière",
    description:
      "Enregistrement fiscal, formalité fusionnée, inscription au Livre Foncier / RCCM.",
    roleResponsable: "clerc_formaliste",
    niveauAlerteParDefaut: "critique",
  },
  {
    id: 6,
    code: "EXPEDITIONS",
    libelle: "Expéditions & archivage",
    description:
      "Délivrance des grosses et expéditions, entrée au minutier, numérotation et archivage.",
    roleResponsable: "archiviste",
    niveauAlerteParDefaut: "normal",
  },
];

const MEMOIRE_ETAPES = new Map(ETAPES_INITIALES.map((e) => [e.id, { ...e }]));

// Persistance fichier locale
const FICHIER_ETAPES_JSON = path.join(
  __dirname,
  "..",
  "data",
  "manuel_etapes.json",
);
try {
  if (fs.existsSync(FICHIER_ETAPES_JSON)) {
    const data = JSON.parse(fs.readFileSync(FICHIER_ETAPES_JSON, "utf8"));
    if (Array.isArray(data)) {
      data.forEach((e) => {
        if (e && e.id) MEMOIRE_ETAPES.set(Number(e.id), { ...e });
      });
    }
  }
} catch (_) {}

function sauvegarderSurDisque() {
  try {
    const dir = path.dirname(FICHIER_ETAPES_JSON);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(
      FICHIER_ETAPES_JSON,
      JSON.stringify(Array.from(MEMOIRE_ETAPES.values()), null, 2),
    );
  } catch (_) {}
}

async function listerEtapes() {
  try {
    const { rows } = await pool.query(
      "SELECT * FROM etapes_pipeline ORDER BY id",
    );
    if (rows && rows.length) {
      const etapes = rows.map(versCamel);
      etapes.forEach((e) => MEMOIRE_ETAPES.set(e.id, e));
      return etapes;
    }
  } catch (_) {}

  return Array.from(MEMOIRE_ETAPES.values()).sort((a, b) => a.id - b.id);
}

async function obtenirEtape(id) {
  const idNum = Number(id);
  try {
    const { rows } = await pool.query(
      "SELECT * FROM etapes_pipeline WHERE id = $1",
      [idNum],
    );
    if (rows && rows.length) return versCamel(rows[0]);
  } catch (_) {}

  return MEMOIRE_ETAPES.get(idNum) || null;
}

async function modifierEtape(
  id,
  { description, roleResponsable, niveauAlerteParDefaut },
) {
  const idNum = Number(id);
  let etapeModifiee = null;

  try {
    const { rows } = await pool.query(
      `UPDATE etapes_pipeline SET
         description = COALESCE($1, description),
         role_responsable = COALESCE($2, role_responsable),
         niveau_alerte_par_defaut = COALESCE($3, niveau_alerte_par_defaut)
       WHERE id = $4 RETURNING *`,
      [description, roleResponsable, niveauAlerteParDefaut, idNum],
    );
    if (rows && rows.length) etapeModifiee = versCamel(rows[0]);
  } catch (_) {}

  const existante = MEMOIRE_ETAPES.get(idNum) ||
    ETAPES_INITIALES.find((e) => e.id === idNum) || {
      id: idNum,
      code: `ETAPE_${idNum}`,
      libelle: `Étape ${idNum}`,
    };
  const maj = {
    ...existante,
    description:
      description !== undefined ? description : existante.description,
    roleResponsable:
      roleResponsable !== undefined
        ? roleResponsable
        : existante.roleResponsable,
    niveauAlerteParDefaut:
      niveauAlerteParDefaut !== undefined
        ? niveauAlerteParDefaut
        : existante.niveauAlerteParDefaut,
  };
  MEMOIRE_ETAPES.set(idNum, maj);
  sauvegarderSurDisque();

  return etapeModifiee || maj;
}

module.exports = {
  listerEtapes,
  obtenirEtape,
  modifierEtape,
  ETAPES_INITIALES,
};

