      "SELECT * FROM dossier_projets_acte WHERE dossier_id = $1 ORDER BY numero_version DESC LIMIT 1",
      [dossierId],
    );
    if (rows && rows.length) return versCamel(rows[0]);
  } catch (errDb) {
