async function obtenirTranchesBareme(baremeEmolumentsId) {
  if (!baremeEmolumentsId) return [];
  const baremeLocal = Array.from(MEMOIRE_BAREMES.values()).find(
    (b) => b.id === baremeEmolumentsId || b.code === baremeEmolumentsId,
  );

  try {
    const { rows: bRows } = await pool.query(
      "SELECT libelle, code FROM baremes_emoluments WHERE id = $1 OR code = $1",
      [baremeEmolumentsId],
    );
    const { rows } = await pool.query(
      `SELECT t.id, t.ordre, t.jusqua, t.taux
       FROM baremes_emoluments_tranches t
       JOIN baremes_emoluments b ON b.id = t.bareme_id
       WHERE b.id = $1 OR b.code = $1
       ORDER BY t.ordre`,
      [baremeEmolumentsId],
    );
    if (rows && rows.length) {
      const res = rows.map((r) => ({
        id: r.id,
        ordre: r.ordre,
        jusqua: r.jusqua === null ? null : Number(r.jusqua),
        taux: Number(r.taux),
      }));
      if (bRows && bRows.length) {
        res.baremeLibelle = bRows[0].libelle;
        res.baremeCode = bRows[0].code;
      }
      return res;
    }
  } catch (_) {}

  if (baremeLocal) {
    const tr = (baremeLocal.tranches || []).map((t) => ({ ...t }));
    tr.baremeLibelle = baremeLocal.libelle;
    tr.baremeCode = baremeLocal.code;
    return tr;
  }
  return [];
}

async function modifierDureeTache(tacheId, dureeJours) {
  try {
    const { rows } = await pool.query(
      "UPDATE taches_standard SET duree_jours = $1, updated_at = now() WHERE id = $2 RETURNING *",
      [dureeJours, tacheId],
    );
    if (rows && rows.length) {
      await pool.query(
        `UPDATE types_actes SET delai_standard_jours = (
           SELECT COALESCE(SUM(duree_jours), 0) FROM taches_standard
           WHERE type_acte_id = $1 AND archived_at IS NULL
         ) WHERE id = $1`,
        [rows[0].type_acte_id],
      );
      return tacheStandardVersCamel(rows[0]);
    }
  } catch (_) {}

  // Mise à jour mémoire
  for (const [typeActeId, listeTaches] of MEMOIRE_TACHES_MAP.entries()) {
    const t = listeTaches.find((x) => x.id === tacheId);
    if (t) {
      t.dureeJours = Number(dureeJours) || 1;
      const typeActe = MEMOIRE_TYPES_ACTES.get(typeActeId);
      if (typeActe) {
        typeActe.delaiStandardJours = listeTaches.reduce(
          (s, x) => s + (Number(x.dureeJours) || 0),
          0,
        );
      }
      break;
    }
  }

  return { id: tacheId, dureeJours };
}

async function creerTypeActe(donnees) {
  const {
    classificationId,
    libelle,
    baremeEmolumentsId,
    droitEnregistrementMode = "pourcentage",
    droitEnregistrementValeur = 0,
    taxeFonciereApplicable = false,
    taches,
  } = donnees;

  // Calcul dynamique du délai standard comme somme des durées de tâches
  let delaiStandardJours = Number(donnees.delaiStandardJours) || 0;
  if (Array.isArray(taches) && taches.length > 0) {
    delaiStandardJours = taches.reduce(
      (sum, t) => sum + (Number(t.dureeJours) || 0),
      0,
    );
  }
  if (!delaiStandardJours) delaiStandardJours = 15;

  const id =
    "acte_" +
    (libelle
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "_")
      .slice(0, 30) || crypto.randomUUID().slice(0, 8));

  try {
    const { rows } = await pool.query(
      `INSERT INTO types_actes (id, classification_id, libelle, delai_standard_jours, bareme_emoluments_id, droit_enregistrement_mode, droit_enregistrement_valeur, taxe_fonciere_applicable, actif)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, true)
       RETURNING *`,
      [
        id,
        classificationId || "classif_immo",
        libelle,
        delaiStandardJours,
        baremeEmolumentsId || null,
        droitEnregistrementMode,
        droitEnregistrementValeur,
        Boolean(taxeFonciereApplicable),
      ],
    );
    if (rows && rows.length) {
      if (Array.isArray(taches) && taches.length > 0) {
        for (let i = 0; i < taches.length; i++) {
          const t = taches[i];
          const tId = "tache_" + crypto.randomUUID().slice(0, 8);
          await pool
            .query(
              `INSERT INTO taches_standard (id, type_acte_id, etape, ordre, libelle, duree_jours, bloquante)
             VALUES ($1, $2, $3, $4, $5, $6, $7)`,
              [
                tId,
                id,
                t.etape || i + 1,
                t.ordre || i + 1,
                t.libelle,
                t.dureeJours || 2,
                t.bloquante !== false,
              ],
            )
            .catch(() => {});
        }
      }
      return typeActeVersCamel(rows[0]);
    }
  } catch (_) {}

  const nouvelActe = {
    id,
    classificationId: classificationId || "classif_immo",
    libelle,
    delaiStandardJours: Number(delaiStandardJours) || 15,
    baremeEmolumentsId: baremeEmolumentsId || null,
    droitEnregistrementMode: droitEnregistrementMode || "pourcentage",
    droitEnregistrementValeur: Number(droitEnregistrementValeur) || 0,
    taxeFonciereApplicable: Boolean(taxeFonciereApplicable),
    actif: true,
  };
  MEMOIRE_TYPES_ACTES.set(id, nouvelActe);

  if (Array.isArray(taches) && taches.length > 0) {
    const tachesFormatees = taches.map((t, idx) => ({
      id: "tache_" + crypto.randomUUID().slice(0, 8),
      typeActeId: id,
      etape: t.etape || idx + 1,
      ordre: t.ordre || idx + 1,
      libelle: t.libelle,
      dureeJours: Number(t.dureeJours) || 2,
      bloquante: t.bloquante !== false,
    }));
    MEMOIRE_TACHES_MAP.set(id, tachesFormatees);
  }

  return nouvelActe;
}

async function ajouterTacheStandard(typeActeId, donnees) {
  const {
    etape = 1,
    ordre = 1,
    libelle,
    dureeJours = 2,
    bloquante = true,
